echo "K3 MarkerRow: useArrangement() calls $(grep -c 'useArrangement()' $M) forwardRef $(grep -c 'forwardRef' $M) memo $(grep -c '^export const ArrangementMarkerRowView = memo(ArrangementMarkerRowViewInner);$' $M) actions hook $(grep -c '^export function useArrangementMarkerRowActions' $M) handleRef $(grep -c 'handleRef' $M) markers derivation in view $(grep -c 'const markers = arrangementMarkers(arrangement);' $M)"
