echo "K18 marker recipe sketch == HEAD: $(python3 -I -c "import json;s=json.load(open('$B/probe/marker-sketch-379.json'));h=json.load(open('$B/probe/marker-head-379.json'));print([vp for vp in ('1440x900','1280x720') if s[vp]==h[vp] and 'error' not in s[vp]])")"
